from gen import *
from scipy.ndimage import label
from vision import CAL
# Fit common marker by intersection of camera RGB rays (independent of depth).
def ray(cam,uv):
 K=np.array(CAL[cam]['intrinsic_cv']);T=np.array(CAL[cam]['cam2world_gl']);d=np.array([(uv[0]-K[0,2])/K[0,0],-(uv[1]-K[1,2])/K[1,1],-1]);d=T[:3,:3]@d;d/=np.linalg.norm(d);return T[:3,3],d
def triangulate(observations):
 A=[];b=[]
 for cam,uv in observations:
  o,d=ray(cam,uv);m=np.eye(3)-np.outer(d,d);A.append(m);b.append(m@o)
 p=np.linalg.lstsq(np.concatenate(A),np.concatenate(b),rcond=None)[0]
 return p,[(cam,np.round(project(cam,p)-uv,2)) for cam,uv in observations]
